#include <bits/stdc++.h>
using namespace std;
int lo, hi, k;
int memo[32][64];
bool seen[32][64];
// Best XOR of the remaining low bits, or -1; flags: a/b tight to lo/hi, a<b already, xor tight to k.
int visit(int bit, int al, int ah, int bl, int bh, int less, int tight) {
    if (bit < 0) return less ? 0 : -1;
    int state = al | ah << 1 | bl << 2 | bh << 3 | less << 4 | tight << 5;
    if (seen[bit][state]) return memo[bit][state];
    int l = (lo >> bit) & 1, h = (hi >> bit) & 1, limit = (k >> bit) & 1, best = -1;
    for (int a = 0; a < 2; a++) {
        if ((al && a < l) || (ah && a > h)) continue;
        for (int b = 0; b < 2; b++) {
            if ((bl && b < l) || (bh && b > h) || (!less && a > b)) continue;
            int z = a ^ b;
            if (tight && z > limit) continue;
            int rest = visit(bit - 1, al && a == l, ah && a == h, bl && b == l, bh && b == h, less || a < b, tight && z == limit);
            if (rest >= 0) best = max(best, (z << bit) + rest);
        }
    }
    seen[bit][state] = true;
    return memo[bit][state] = best;
}
int main() {
    cin >> lo >> hi >> k;
    int top = max(hi, k), bits = 0;
    while (top >> bits) bits++;
    cout << visit(bits - 1, 1, 1, 1, 1, 0, 1) << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    static int lo, hi, k;
    static int[][] memo = new int[32][64];
    static boolean[][] seen = new boolean[32][64];

    // Best XOR of the remaining low bits, or -1; flags: a/b tight to lo/hi, a<b already, xor tight to k.
    static int visit(int bit, int al, int ah, int bl, int bh, int less, int tight) {
        if (bit < 0) return less == 1 ? 0 : -1;
        int state = al | ah << 1 | bl << 2 | bh << 3 | less << 4 | tight << 5;
        if (seen[bit][state]) return memo[bit][state];
        int l = (lo >> bit) & 1, h = (hi >> bit) & 1, limit = (k >> bit) & 1, best = -1;
        for (int a = 0; a < 2; a++) {
            if ((al == 1 && a < l) || (ah == 1 && a > h)) continue;
            for (int b = 0; b < 2; b++) {
                if ((bl == 1 && b < l) || (bh == 1 && b > h) || (less == 0 && a > b)) continue;
                int z = a ^ b;
                if (tight == 1 && z > limit) continue;
                int rest = visit(bit - 1, al & (a == l ? 1 : 0), ah & (a == h ? 1 : 0), bl & (b == l ? 1 : 0),
                        bh & (b == h ? 1 : 0), less | (a < b ? 1 : 0), tight & (z == limit ? 1 : 0));
                if (rest >= 0) best = Math.max(best, (z << bit) + rest);
            }
        }
        seen[bit][state] = true;
        return memo[bit][state] = best;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        lo = nextInt();
        hi = nextInt();
        k = nextInt();
        int bits = 32 - Integer.numberOfLeadingZeros(Math.max(hi, k));
        System.out.println(visit(bits - 1, 1, 1, 1, 1, 0, 1));
    }
