package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"math/bits"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

var lo, hi, k int
var memo [32][64]int
var seen [32][64]bool

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

// visit returns the best XOR of the remaining low bits, or -1;
// flags: a/b tight to lo/hi, a<b already, xor tight to k.
func visit(bit, al, ah, bl, bh, less, tight int) int {
	if bit < 0 {
		if less == 1 {
			return 0
		}
		return -1
	}
	state := al | ah<<1 | bl<<2 | bh<<3 | less<<4 | tight<<5
	if seen[bit][state] {
		return memo[bit][state]
	}
	l, h, limit, best := (lo>>bit)&1, (hi>>bit)&1, (k>>bit)&1, -1
	for a := 0; a < 2; a++ {
		if (al == 1 && a < l) || (ah == 1 && a > h) {
			continue
		}
		for b := 0; b < 2; b++ {
			if (bl == 1 && b < l) || (bh == 1 && b > h) || (less == 0 && a > b) {
				continue
			}
			z := a ^ b
			if tight == 1 && z > limit {
				continue
			}
			rest := visit(bit-1, al&b2i(a == l), ah&b2i(a == h), bl&b2i(b == l), bh&b2i(b == h), less|b2i(a < b), tight&b2i(z == limit))
			if rest >= 0 {
				best = max(best, z<<bit+rest)
			}
		}
	}
	seen[bit][state] = true
	memo[bit][state] = best
	return best
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	lo, hi, k = int(nextInt()), int(nextInt()), int(nextInt())
	top := bits.Len(uint(max(hi, k)))
	w.WriteString(strconv.Itoa(visit(top-1, 1, 1, 1, 1, 0, 1)) + "\n")
}
